// ZeroSync push notification worker.
// This is intentionally separate from /sw.js, which is generated by the PWA
// plugin for offline app-shell caching. Push subscriptions must stay attached
// to this stable worker so notification handling is never overwritten by the
// generated offline worker during production builds.

self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));

self.addEventListener("push", (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    try {
      payload = { title: "ZeroSync", body: event.data ? event.data.text() : "" };
    } catch {}
  }

  event.waitUntil(
    (async () => {
      try {
        if (typeof payload.badgeCount === "number" && "setAppBadge" in self.navigator) {
          if (payload.badgeCount > 0) await self.navigator.setAppBadge(payload.badgeCount);
          else await self.navigator.clearAppBadge?.();
        }
      } catch {}

      const targetUrl = payload.url || "/";
      const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      const targetPath = new URL(targetUrl, self.location.origin).pathname;
      const focusedOnTarget = all.some((client) => {
        try {
          const url = new URL(client.url);
          return (
            payload.tag !== "test" &&
            url.origin === self.location.origin &&
            url.pathname === targetPath &&
            client.visibilityState === "visible" &&
            client.focused
          );
        } catch {
          return false;
        }
      });

      for (const client of all) {
        try { client.postMessage({ type: "push", payload }); } catch {}
      }

      if (focusedOnTarget) return;

      await self.registration.showNotification(payload.title || "ZeroSync", {
        body: payload.body || "",
        icon: payload.icon || "/icon-192.png",
        badge: payload.badge || "/icon-192.png",
        tag: payload.tag || undefined,
        renotify: !!payload.tag,
        data: { url: targetUrl, ...(payload.data || {}) },
        requireInteraction: payload.tag === "test",
      });
    })(),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetUrl = (event.notification.data && event.notification.data.url) || "/";
  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      for (const client of all) {
        try {
          const url = new URL(client.url);
          if (url.origin === self.location.origin) {
            await client.focus();
            if ("navigate" in client) await client.navigate(targetUrl);
            return;
          }
        } catch {}
      }
      await self.clients.openWindow(targetUrl);
    })(),
  );
});